/* Browser-local fictional demo. Assignments never grant account permissions. */
(function(root){'use strict';
const R=root.Reunion;
const ROLES={lead:'全体統括',deputy:'副統括',accounting:'会計担当',system:'システム担当',publicity:'広報担当',venue:'会場担当',planning:'企画運営担当',guest:'恩師・来賓対応',support:'応援者・協力者対応',reception:'受付担当',mc:'司会',photography:'写真撮影',recording:'記録担当',reunion:'二次会担当',accessibility:'案内・配慮対応',other:'その他'};
const STATUS={planned:'依頼・調整中',active:'担当決定',done:'完了',inactive:'担当解除'};
function prepare(s){s.duties??=[];}
function staff(s,uid,write=false){const p=s.people.find(p=>p.id===Number(uid));if(!p||!(write?p.role==='owner':['owner','organizer'].includes(p.role)))throw new Error(write?'担当の設定は管理者が行います。':'幹事権限が必要です。');return p;}
function txt(v,max,required=false){v=String(v??'').trim();if(v.length>max||required&&!v)throw new Error('必須項目と文字数を確認してください。');return v;}
function save(s,d,uid){prepare(s);const a=staff(s,uid,true),id=Number(d.id||0),old=id?s.duties.find(x=>x.id===id):null;if(id&&!old)throw new Error('担当記録がありません。');if(old&&Number(d.revision)!==old.revision)throw new Error('他の操作で更新されています。画面を開き直してください。');const roleKey=String(d.roleKey||'');if(!ROLES[roleKey])throw new Error('役割を選択してください。');const kind=String(d.kind||'');if(!['member','external'].includes(kind))throw new Error('担当者の区分を選択してください。');const userId=kind==='member'?Number(d.userId):null;const person=userId?s.people.find(p=>p.id===userId):null;if(kind==='member'&&!person)throw new Error('登録者を選択してください。');const externalName=kind==='external'?txt(d.externalName,100,true):'';const status=String(d.status||'active');if(!STATUS[status])throw new Error('担当状況を選択してください。');const cl=Number(d.class||0);if(!Number.isInteger(cl)||cl<0||cl>10)throw new Error('対象クラスを確認してください。');const date=txt(d.dueDate,10);if(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date))throw new Error('対応予定日を確認してください。');const x={id:id||Math.max(0,...s.duties.map(x=>x.id))+1,revision:(old?.revision||0)+1,roleKey,customRole:roleKey==='other'?txt(d.customRole,100,true):'',kind,userId,externalName,class:cl,scope:txt(d.scope,200),description:txt(d.description,2000),contact:kind==='external'?txt(d.contact,300):'',note:txt(d.note,2000),status,dueDate:date,created:old?.created||new Date().toISOString(),updated:new Date().toISOString()};const reason=txt(d.reason,1000,true);R.audit(s,a.name,'担当・役割を設定','duty:'+x.id,old?R.clone(old):null,x,reason);if(old)Object.assign(old,x);else s.duties.push(x);return x;}
function rows(s,uid){prepare(s);staff(s,uid);const cls=(s.classContacts||[]).map(c=>({id:'c'+c.id,source:'class',roleKey:'class',label:'クラス幹事',userId:c.userId,kind:'member',class:c.class,status:'active',scope:'表示順 '+c.position,description:'クラスの連絡・登録確認',dueDate:'',name:s.people.find(p=>p.id===c.userId)?.name||'未登録',personClass:s.people.find(p=>p.id===c.userId)?.class||0}));return [...cls,...s.duties.map(x=>({...x,source:'duty',label:x.roleKey==='other'?x.customRole:ROLES[x.roleKey],name:x.kind==='external'?x.externalName:s.people.find(p=>p.id===x.userId)?.name||'未登録',personClass:x.kind==='external'?0:s.people.find(p=>p.id===x.userId)?.class||0}))];}
function own(s,uid){prepare(s);return [...(s.classContacts||[]).filter(c=>c.userId===Number(uid)).map(c=>({label:'クラス幹事',scope:'3年'+c.class+'組',description:'クラスの連絡・登録確認',status:'active',dueDate:''})),...s.duties.filter(x=>x.userId===Number(uid)&&x.kind==='member'&&x.status!=='inactive').map(x=>({label:x.roleKey==='other'?x.customRole:ROLES[x.roleKey],scope:x.scope,description:x.description,status:x.status,dueDate:x.dueDate}))];}
function filter(rows,f,uid){const q=String(f.q||'').trim().toLocaleLowerCase();return rows.filter(x=>(!q||[x.name,x.label,x.scope,x.description].join(' ').toLocaleLowerCase().includes(q))&&(!f.role||x.roleKey===f.role)&&(!f.class||x.class===Number(f.class)||x.personClass===Number(f.class))&&(!f.kind||x.kind===f.kind)&&(!f.status||x.status===f.status)&&(f.mine!=='yes'||x.userId===Number(uid)));}
root.Duties={ROLES,STATUS,prepare,save,rows,own,filter};if(typeof module!=='undefined')module.exports=root.Duties;
})(typeof globalThis!=='undefined'?globalThis:this);
